using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class CompanionEffects : UnitEffects
{
	[Header("Companion Components")]
	[SerializeField]
	public bool companionForBattle;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionEffectsList companionEffectsList;

	[SerializeField]
	[ShowIf("companionForBattle")]
	private CompanionAbility companionAbility;

	private bool justRecycled;

	private List<StartingEffect> previousEffects = new List<StartingEffect>();

	private bool nextTimeRepairedRestorePreviousEffects;

	[ShowNonSerializedField]
	private bool wasBoosted;

	public CompanionEffectsList CompanionEffectsList => companionEffectsList;

	public bool JustRecycled => justRecycled;

	public bool WasBoosted => wasBoosted;

	public void SetJustRecycled(bool value)
	{
		justRecycled = value;
	}

	public void SetNextTimeRepairedRestorePreviousEffects(bool value)
	{
		nextTimeRepairedRestorePreviousEffects = value;
	}

	public void SetWasBoosted(bool value)
	{
		wasBoosted = value;
	}

	public void ResetPreviousEffectsVariables()
	{
		wasBoosted = false;
		previousEffects.Clear();
		nextTimeRepairedRestorePreviousEffects = false;
	}

	public void Initialize(RuntimeCompanion runtimeCompanion, bool effectFeedback, bool isPreviewCompanion = false)
	{
		if (companionForBattle)
		{
			SetJustRecycled(value: false);
			RemoveAllEffectsWithCallbacks();
		}
		else
		{
			RemoveAllEffectWithoutCallbacks();
		}
		if (activeEffectsList.Count > 0)
		{
			Debug.Log("-----------------COMPANION EFFECTS Initialize: activeEffectsList.Count > 0 when it shouldnt, cleaning it-----------------------");
			activeEffectsList.Clear();
		}
		ToggleLinksNoFeedback(!effectFeedback);
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			bool effectFeedback2 = false;
			if (companionForBattle && effectFeedback)
			{
				effectFeedback2 = true;
			}
			int renderLayer = -1;
			if (isPreviewCompanion)
			{
				renderLayer = 10;
			}
			List<StartingEffect> combinedEffects = runtimeCompanion.GetCombinedEffects();
			for (int i = 0; i < combinedEffects.Count; i++)
			{
				StartingEffect startingEffect = combinedEffects[i];
				AddEffect(startingEffect.Effect, startingEffect.EffectAmount, effectFeedback2, companionForBattle, null, gainingEffectVFXAndSFX: true, renderLayer);
			}
			if (companionForBattle && nextTimeRepairedRestorePreviousEffects)
			{
				for (int j = 0; j < combinedEffects.Count; j++)
				{
					StartingEffect startingEffect2 = combinedEffects[j];
					for (int num = previousEffects.Count - 1; num >= 0; num--)
					{
						if (startingEffect2.Effect == previousEffects[num].Effect)
						{
							if (startingEffect2.EffectAmount < previousEffects[num].EffectAmount)
							{
								previousEffects[num].IncreaseEffectAmount(-startingEffect2.EffectAmount);
							}
							else
							{
								previousEffects.RemoveAt(num);
							}
						}
					}
				}
				for (int k = 0; k < previousEffects.Count; k++)
				{
					AddEffect(previousEffects[k].Effect, previousEffects[k].EffectAmount, effectFeedback2, companionForBattle, null, gainingEffectVFXAndSFX: true, renderLayer);
				}
			}
			ResetPreviousEffectsVariables();
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
			{
				ToggleLinksNoFeedback(value: false);
			});
		});
	}

	public void EndOfBattleInitializeAliveCompanion(List<StartingEffect> startingEffects)
	{
		ResetPreviousEffectsVariables();
		SetJustRecycled(value: false);
		ToggleLinksNoFeedback(value: true);
		RemoveAllEffectsWithCallbacks();
		if (activeEffectsList.Count > 0)
		{
			Debug.Log("-----------------COMPANION EFFECTS EndOfBattleInitializeAliveCompanion: activeEffectsList.Count > 0 when it shouldnt, cleaning it-----------------------");
			activeEffectsList.Clear();
		}
		InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
		{
			for (int i = 0; i < startingEffects.Count; i++)
			{
				StartingEffect startingEffect = startingEffects[i];
				AddEffect(startingEffect.Effect, startingEffect.EffectAmount, effectFeedback: false);
			}
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
			{
				ToggleLinksNoFeedback(value: false);
			});
		});
	}

	private void ToggleLinksNoFeedback(bool value)
	{
		companionEffectsList.ThornLinkEffect.NoFeeback = value;
		companionEffectsList.SkinLinkEffect.NoFeeback = value;
		companionEffectsList.BoostLinkEffect.NoFeeback = value;
		companionEffectsList.EmpowerLinkEffect.NoFeeback = value;
	}

	public void UpdateUpgradedCompanionEffects(List<StartingEffect> startingEffects)
	{
		List<StartingEffect> list = new List<StartingEffect>();
		List<EffectInstance> list2 = new List<EffectInstance>();
		for (int i = 0; i < startingEffects.Count; i++)
		{
			StartingEffect startingEffect = startingEffects[i];
			bool flag = false;
			for (int j = 0; j < activeEffectsList.Count; j++)
			{
				EffectInstance effectInstance = activeEffectsList[j];
				if (startingEffect.Effect == effectInstance.Effect)
				{
					flag = true;
					if (startingEffect.EffectAmount > effectInstance.EffectAmount)
					{
						int effectAmount = startingEffect.EffectAmount - effectInstance.EffectAmount;
						list.Add(new StartingEffect(startingEffect.Effect, effectAmount));
					}
				}
			}
			if (!flag)
			{
				list.Add(new StartingEffect(startingEffect));
			}
		}
		for (int k = 0; k < activeEffectsList.Count; k++)
		{
			EffectInstance effectInstance2 = activeEffectsList[k];
			bool flag2 = false;
			for (int l = 0; l < startingEffects.Count; l++)
			{
				StartingEffect startingEffect2 = startingEffects[l];
				if (effectInstance2.Effect == startingEffect2.Effect)
				{
					flag2 = true;
				}
			}
			if (!flag2)
			{
				list2.Add(effectInstance2);
			}
		}
		for (int num = list2.Count - 1; num >= 0; num--)
		{
			RemoveEffectWithoutCallbacks(list2[num]);
		}
		for (int m = 0; m < list.Count; m++)
		{
			AddEffect(list[m].Effect, list[m].EffectAmount, companionForBattle, companionForBattle);
		}
	}

	public override bool OnBeforeBeforeDrawDicePhaseEffect()
	{
		return new List<bool>
		{
			IsEffectActiveWithActivation(effectsList.RuinEffect, activateFeedback: false),
			IsEffectActiveWithActivation(effectsList.NefariousPulseEffect, activateFeedback: false)
		}.Contains(item: true);
	}

	public override bool OnBeforeDrawDicePhaseEffects()
	{
		List<bool> list = new List<bool>();
		list.Add(IsEffectActiveWithActivation(companionEffectsList.ShadowyReflectionEffect));
		list.Add(base.OnBeforeDrawDicePhaseEffects());
		companionAbility.RestoreDiceToDefaultState();
		UnitsDiceActivation component = GetComponent<UnitsDiceActivation>();
		if (IsEffectActiveAndDecreaseEffect(companionEffectsList.OptimizeEffect, 1))
		{
			component.TurnPurifiesIntoNewAction(companionEffectsList.OptimizeEffect);
			list.Add(item: true);
		}
		if (!IsEffectActiveWithActivation(companionEffectsList.BoostEffect))
		{
			if (component.IsBoosted)
			{
				list.Add(item: true);
			}
			component.Boosted(boost: false);
		}
		return list.Contains(item: true);
	}

	public void CheckBoostStartOfTurnRepair()
	{
		IsEffectActiveWithActivation(companionEffectsList.BoostEffect);
	}

	public override bool OnStartTurnEffects()
	{
		return new List<bool>
		{
			IsEffectActiveWithActivation(companionEffectsList.DischargeEffect, activateFeedback: false),
			IsEffectActiveWithActivation(companionEffectsList.AutoTurretEffect, activateFeedback: false),
			base.OnStartTurnEffects()
		}.Contains(item: true);
	}

	public override bool OnEndTurnEffects()
	{
		List<bool> obj = new List<bool> { IsEffectActiveWithActivation(companionEffectsList.HealbotEffect, activateFeedback: false) };
		RemoveEffect(effectsList.ShadowMantleEffect);
		obj.Add(IsEffectActiveWithActivation(effectsList.UnholyMistEffect));
		obj.Add(base.OnEndTurnEffects());
		return obj.Contains(item: true);
	}

	public override bool OnEndTurnDecreaseEffects()
	{
		return new List<bool>
		{
			base.OnEndTurnDecreaseEffects(),
			IsEffectActiveAndDecreaseEffect(effectsList.DisorientedEffect, 1)
		}.Contains(item: true);
	}

	public override void OnPurifyEffects(float currentCorruption, GameObject source, int purifyAmount)
	{
		base.OnPurifyEffects(currentCorruption, source, purifyAmount);
		if (IsEffectActive(companionEffectsList.PurificationOverflowEffect, activateFeedback: false))
		{
			AddEffect(companionEffectsList.PurificationOverflowEffect, purifyAmount);
		}
		IsEffectActiveWithActivationWithPurifyAmountAndSource(companionEffectsList.MultiphaseEffect, purifyAmount, source, activateFeedback: false, updateAmount: false);
	}

	public override void OnCorruptEffects(GameObject source, int corruptAmount)
	{
		base.OnCorruptEffects(source, corruptAmount);
		if (corruptAmount > 0)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerOrSentinelsCorruptedDivinePrismAction(corruptAmount * 2);
			if (IsEffectActive(companionEffectsList.CorruptionOverflowEffect, activateFeedback: false))
			{
				AddEffect(companionEffectsList.CorruptionOverflowEffect, corruptAmount);
			}
		}
		IsEffectActiveWithActivationWithCorruptAmountAndSource(companionEffectsList.MultiphaseEffect, corruptAmount, source, activateFeedback: false, updateAmount: false);
		ReferenceSingleton<HeveliusOmensHandler>.Instance.OnSentinelsCorruptedActivateShiningApparatus(base.gameObject);
	}

	public override void OnRuneCasted(RuneInstance runeInstance)
	{
		if (IsEffectActive(companionEffectsList.AstralEmpowerEffect, activateFeedback: false))
		{
			AddEffect(companionEffectsList.AstralEmpowerEffect, 1);
		}
	}

	public void ActivateAreaPurifyCorruptOnBreakEffects(bool recycle)
	{
		SetJustRecycled(recycle);
		IsEffectActiveWithActivation(companionEffectsList.RandiantBombEffect, activateFeedback: false);
		IsEffectActiveWithActivation(companionEffectsList.CorruptionBlastEffect, activateFeedback: false);
	}

	public override void OnShuffleDicePoolEffects()
	{
		IsEffectActiveWithActivation(companionEffectsList.ExpelEffect, activateFeedback: false);
	}

	public int IsBoostLinkEffectActiveGetAmount()
	{
		return IsEffectActiveGetAmount(companionEffectsList.BoostLinkEffect, activateFeedback: false);
	}

	public int IsBoostLinkEffectActiveGetCorruptionIncreaseAmount()
	{
		return IsLinkActiveGetCorruptionIncreaseAmount(companionEffectsList.BoostLinkEffect);
	}

	public int IsLinkRockPlateActiveGetCorruptionIncreaseAmount()
	{
		return IsLinkActiveGetCorruptionIncreaseAmount(companionEffectsList.SkinLinkEffect);
	}

	public int IsLinkEmpowerActiveGetCorruptionIncreaseAmount()
	{
		return IsLinkActiveGetCorruptionIncreaseAmount(companionEffectsList.EmpowerLinkEffect);
	}

	public int IsLinkThornActiveGetCorruptionIncreaseAmount()
	{
		return IsLinkActiveGetCorruptionIncreaseAmount(companionEffectsList.ThornLinkEffect);
	}

	public int IsLinkActiveGetCorruptionIncreaseAmount(HeveliusLinkEffect heveliusLinkEffect)
	{
		if (IsEffectActive(heveliusLinkEffect, activateFeedback: false) && heveliusLinkEffect.IncreaseCorruptionReceived)
		{
			if (heveliusLinkEffect.EnableIncreaseCorruptionReceivedFixedAmount)
			{
				return heveliusLinkEffect.IncreaseCorruptionReceivedFixedAmount;
			}
			return IsEffectActiveGetAmount(heveliusLinkEffect, activateFeedback: false);
		}
		return 0;
	}

	public int IsLinksActiveGetAmount()
	{
		return 0 + (IsEffectActive(companionEffectsList.BoostLinkEffect, activateFeedback: false) ? 1 : 0) + (IsEffectActive(companionEffectsList.SkinLinkEffect, activateFeedback: false) ? 1 : 0) + (IsEffectActive(companionEffectsList.EmpowerLinkEffect, activateFeedback: false) ? 1 : 0) + (IsEffectActive(companionEffectsList.ThornLinkEffect, activateFeedback: false) ? 1 : 0);
	}

	public void SavePreviousEffects()
	{
		wasBoosted = companionAbility.IsBoosted;
		for (int i = 0; i < activeEffectsList.Count; i++)
		{
			previousEffects.Add(new StartingEffect(activeEffectsList[i].Effect, activeEffectsList[i].EffectAmount));
		}
	}

	public bool IsBoostActive()
	{
		return IsEffectActive(companionEffectsList.BoostEffect, activateFeedback: false);
	}

	public int IsDischargeActiveGetCorruptionIncreaseAmount()
	{
		if (IsEffectActive(companionEffectsList.DischargeEffect, activateFeedback: false) && companionEffectsList.DischargeEffect.IncreaseCorruptionReceived)
		{
			if (companionEffectsList.DischargeEffect.EnableIncreaseCorruptionReceivedFixedAmount)
			{
				return companionEffectsList.DischargeEffect.IncreaseCorruptionReceivedFixedAmount;
			}
			return IsEffectActiveGetAmount(companionEffectsList.DischargeEffect, activateFeedback: false);
		}
		return 0;
	}

	public void EnemyOvercorruptedIsLockOnAndAutoTurretActiveActivateWithSource(GameObject source)
	{
		if (IsEffectActive(companionEffectsList.LockOnEffect, activateFeedback: false))
		{
			IsEffectActiveWithActivationWithSource(companionEffectsList.AutoTurretEffect, source, activateFeedback: false);
		}
	}

	public override void ToggleActionValueModifier(ActionValueModifier actionValueModifier)
	{
		companionAbility.ToggleActionValueModifier(actionValueModifier);
	}

	public override void UpdateActionValueModifier()
	{
		companionAbility.UpdateActionValueModifier();
	}
}
